css:
.print-format { font-family:Manjari, sans-serif !important; font-size:11.5pt !important; line-height:1.35; padding:0 !important; color:#000; }
.annexure p { margin:0; }
.annexure .number { text-align:right; font-weight:bold; }
.annexure .number span, .annexure h3 span { border-bottom:1pt solid #000; padding-bottom:1pt; }
.annexure h3 { text-align:center; font-size:13pt; font-weight:bold; margin:10pt 0 3pt; }
.annexure .subtitle { text-align:center; font-size:9.5pt; margin:0 0 9pt; }
.annexure table { width:100%; border-collapse:collapse; }
.annexure table.form { table-layout:fixed; }
.annexure table.form td { border:0.75pt solid #000 !important; padding:3.5pt 6pt !important; vertical-align:middle !important; }
.annexure table.form td.sl { text-align:center; }
.annexure table.form td.answer { white-space:pre-line; word-wrap:break-word; }
.annexure table.plain td { border:0 !important; padding:0 !important; vertical-align:bottom !important; }
.annexure .signature { margin-top:18pt; }
.annexure .signature td { padding-top:4pt !important; }
.annexure .cut { border-top:1.5pt dashed #000; margin:8pt 0 12pt; }
.annexure .receipt-title { text-align:center; font-weight:bold; font-size:12pt; margin:0 0 2pt; }
.annexure .receipt-note { text-align:center; margin:0 0 10pt; }
.annexure table.fields td { padding:4.5pt 0 0 !important; }
.annexure table.fields td.lbl { white-space:nowrap; width:1%; padding-right:8pt !important; }
.annexure table.fields td.fill { border-bottom:1pt dotted #000 !important; }
.annexure .seal { margin-top:16pt; }
.annexure .seal td.fill { border-bottom:1pt dotted #000 !important; width:45%; }
